# A small, explanatory flake excerpt
{
  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";
    home-manager = {
      url = "github:nix-community/home-manager";
      inputs.nixpkgs.follows = "nixpkgs";
    };
    fenix.url = "github:nix-community/fenix";
  };

  # flake.lock records the exact input revisions.
  # NixOS and Home Manager build together.
}

# A small, explanatory editor excerpt
{ pkgs, ... }: {
  programs.neovim = {
    enable = true;
    defaultEditor = true;
    viAlias = true;
    vimAlias = true;
    extraPackages = with pkgs; [
      gopls
      typescript-language-server
      nil
      pyright
      rust-analyzer
      stylua
    ];
  };
}
